package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var sessionStore = make(map[string]string)

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://appuser:apppass@localhost:5432/webapp?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func generateSession() string {
	b := make([]byte, 32)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}
	username := r.FormValue("username")
	password := r.FormValue("password")

	// NOTE: parameterized query for login - this is safe
	var id int
	err := db.QueryRow("SELECT id FROM users WHERE username=$1 AND password=crypt($2, password)", username, password).Scan(&id)
	if err != nil {
		http.Error(w, "Invalid credentials", 401)
		return
	}
	sess := generateSession()
	sessionStore[sess] = username
	http.SetCookie(w, &http.Cookie{Name: "session", Value: sess, Path: "/", HttpOnly: true})
	http.Redirect(w, r, "/dashboard", 302)
}

func dashboardHandler(w http.ResponseWriter, r *http.Request) {
	cookie, err := r.Cookie("session")
	if err != nil || sessionStore[cookie.Value] == "" {
		http.Redirect(w, r, "/login", 302)
		return
	}

	// Template rendering with user-controlled data
	userMsg := r.URL.Query().Get("msg")
	if userMsg == "" {
		userMsg = "Welcome back"
	}

	// VULNERABLE: Server-Side Template Injection via text/template
	tmplStr := fmt.Sprintf(`<html><body><h1>Dashboard</h1><p>%s, {{.Username}}</p>
	<form action="/search" method="GET">
	<input name="q" placeholder="Search reports..."/>
	<button type="submit">Search</button>
	</form></body></html>`, userMsg)

	tmpl, err := template.New("dash").Parse(tmplStr)
	if err != nil {
		http.Error(w, "Template error", 500)
		return
	}
	data := struct{ Username string }{Username: sessionStore[cookie.Value]}
	tmpl.Execute(w, data)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	cookie, err := r.Cookie("session")
	if err != nil || sessionStore[cookie.Value] == "" {
		http.Redirect(w, r, "/login", 302)
		return
	}

	query := r.URL.Query().Get("q")
	// VULNERABLE: SQL injection in search
	sqlQuery := fmt.Sprintf("SELECT title, created_at FROM reports WHERE owner='%s' AND title LIKE '%%%s%%'", sessionStore[cookie.Value], query)
	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("Query error: %v | SQL: %s", err, sqlQuery)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var title, created string
		rows.Scan(&title, &created)
		results = append(results, fmt.Sprintf("%s (%s)", title, created))
	}
	w.Header().Set("Content-Type", "text/html")
	fmt.Fprintf(w, "<html><body><h2>Results for '%s'</h2><ul>", query)
	for _, r := range results {
		fmt.Fprintf(w, "<li>%s</li>", r)
	}
	fmt.Fprintf(w, "</ul></body></html>")
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		w.WriteHeader(503)
		fmt.Fprintf(w, "unhealthy: %v", err)
		return
	}
	fmt.Fprint(w, "ok")
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	http.HandleFunc("/login", loginHandler)
	http.HandleFunc("/dashboard", dashboardHandler)
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)

	log.Printf("Starting server on :%s", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		log.Fatal(err)
	}
}

// Additional utility - not used in main flow but compiled in
func debugQuery(input string) string {
	// Used during development, left in binary
	return strings.Replace(input, "'", "''", -1)
}
